import{_ as r,a0 as u,w as s,s as i,ao as n,I as p,a1 as o,A as e,x as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何使用Vault安全的存储密码和API密钥 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用Vault安全的存储密码和API密钥 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用Vault安全的存储密码和API密钥 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用Vault安全的存储密码和API密钥 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150506 How to Securely Store Passwords and Api Keys Using Vault","title":"如何使用Vault安全的存储密码和API密钥","tag":"201505","desc":""},"relativePath":"201505/20150506 How to Securely Store Passwords and Api Keys Using Vault.md","filePath":"[post].md"}'),d={name:"201505/20150506 How to Securely Store Passwords and Api Keys Using Vault.md"};function g(V,t,m,h,S,b){const a=u("Link");return s(),i("div",null,[t[19]||(t[19]=n('<h1 id="如何使用vault安全的存储密码和api密钥" tabindex="-1">如何使用Vault安全的存储密码和API密钥 <a class="header-anchor" href="#如何使用vault安全的存储密码和api密钥" aria-label="Permalink to “如何使用Vault安全的存储密码和API密钥”">​</a></h1><p>Vault是用来安全的获取秘密信息的工具，它可以保存密码、API密钥、证书等信息。Vault提供了一个统一的接口来访问秘密信息，其具有健壮的访问控制机制和丰富的事件日志。</p><p>对关键信息的授权访问是一个困难的问题，尤其是当有许多用户角色，并且用户请求不同的关键信息时，例如用不同权限登录数据库的登录配置，用于外部服务的API密钥，SOA通信的证书等。当保密信息由不同的平台进行管理，并使用一些自定义的配置时，情况变得更糟，因此，安全的存储、管理审计日志几乎是不可能的。但Vault为这种复杂情况提供了一个解决方案。</p><h3 id="突出特点" tabindex="-1">突出特点 <a class="header-anchor" href="#突出特点" aria-label="Permalink to “突出特点”">​</a></h3><p><strong>数据加密</strong>：Vault能够在不存储数据的情况下对数据进行加密、解密。开发者们便可以存储加密后的数据而无需开发自己的加密技术，Vault还允许安全团队自定义安全参数。</p><p><strong>安全密码存储</strong>：Vault在将秘密信息（API密钥、密码、证书）存储到持久化存储之前对数据进行加密。因此，如果有人偶尔拿到了存储的数据，这也没有任何意义，除非加密后的信息能被解密。</p><p><strong>动态密码</strong>：Vault可以随时为AWS、SQL数据库等类似的系统产生密码。比如，如果应用需要访问AWS S3 桶，它向Vault请求AWS密钥对，Vault将给出带有租期的所需秘密信息。一旦租用期过期，这个秘密信息就不再存储。</p><p><strong>租赁和更新</strong>：Vault给出的秘密信息带有租期，一旦租用期过期，它便立刻收回秘密信息，如果应用仍需要该秘密信息，则可以通过API更新租用期。</p><p><strong>撤销</strong>：在租用期到期之前，Vault可以撤销一个秘密信息或者一个秘密信息树。</p><h3 id="安装vault" tabindex="-1">安装Vault <a class="header-anchor" href="#安装vault" aria-label="Permalink to “安装Vault”">​</a></h3><p>有两种方式来安装使用Vault。</p><p><strong>1. 预编译的Vault二进制</strong> 能用于所有的Linux发行版，下载地址如下，下载之后，解压并将它放在系统PATH路径下，以方便调用。</p>',12)),p("ul",null,[p("li",null,[o(a,{href:"https://dl.bintray.com/mitchellh/vault/vault_0.1.0_linux_386.zip"},{default:e(()=>[...t[0]||(t[0]=[l("下载预编译的二进制 Vault (32-bit)",-1)])]),_:1})]),p("li",null,[o(a,{href:"https://dl.bintray.com/mitchellh/vault/vault_0.1.0_linux_amd64.zip"},{default:e(()=>[...t[1]||(t[1]=[l("下载预编译的二进制 Vault (64-bit)",-1)])]),_:1})]),p("li",null,[o(a,{href:"https://dl.bintray.com/mitchellh/vault/vault_0.1.0_linux_arm.zip"},{default:e(()=>[...t[2]||(t[2]=[l("下载预编译的二进制 Vault (ARM)",-1)])]),_:1})])]),t[20]||(t[20]=n(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/wget-binary.png" alt="wget binary"></p><p><em>下载相应的预编译的Vault二进制版本。</em></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/unzip.png" alt="vault"></p><p><em>解压下载到本地的二进制版本。</em></p><p>祝贺你！您现在可以使用Vault了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/vault.png" alt=""></p><p><strong>2. 从源代码编译</strong>是另一种在系统中安装Vault的方式。在安装Vault之前需要安装GO和GIT。</p><p>在 <strong>Redhat系统中安装GO</strong> 使用下面的指令：</p><pre><code>sudo yum install go
</code></pre><p>在 <strong>Debin系统中安装GO</strong> 使用下面的指令：</p><pre><code>sudo apt-get install golang
</code></pre><p>或者</p><pre><code>sudo add-apt-repository ppa:gophers/go

sudo apt-get update

sudo apt-get install golang-stable
</code></pre><p>在 <strong>Redhat系统中安装GIT</strong> 使用下面的命令：</p><pre><code>sudo yum install git
</code></pre><p>在 <strong>Debian系统中安装GIT</strong> 使用下面的命令：</p><pre><code>sudo apt-get install git
</code></pre><p>一旦GO和GIT都已被安装好，我们便可以开始从源码编译安装Vault。</p><blockquote><p>将下列的Vault仓库拷贝至GOPATH</p></blockquote><pre><code>https://github.com/hashicorp/vault
</code></pre><blockquote><p>测试下面的文件是否存在，如果它不存在，那么Vault没有被克隆到合适的路径。</p></blockquote><pre><code>$GOPATH/src/github.com/hashicorp/vault/main.go
</code></pre><blockquote><p>执行下面的指令来编译Vault，并将二进制文件放到系统bin目录下。</p></blockquote><pre><code>make dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/installation4.png" alt="path"></p><h3 id="一份vault入门教程" tabindex="-1">一份Vault入门教程 <a class="header-anchor" href="#一份vault入门教程" aria-label="Permalink to “一份Vault入门教程”">​</a></h3><p>我们已经编制了一份Vault的官方交互式教程，并带有它在SSH上的输出信息。</p><p><strong>概述</strong></p><p>这份教程包括下列步骤：</p><ul><li>初始化并启封您的Vault</li><li>在Vault中对您的请求授权</li><li>读写秘密信息</li><li>密封您的Vault</li></ul><h4 id="初始化您的vault" tabindex="-1"><strong>初始化您的Vault</strong> <a class="header-anchor" href="#初始化您的vault" aria-label="Permalink to “初始化您的Vault”">​</a></h4><p>首先，我们需要为您初始化一个Vault的工作实例。在初始化过程中，您可以配置Vault的密封行为。简单起见，现在使用一个启封密钥来初始化Vault，命令如下：</p><pre><code>vault init -key-shares=1 -key-threshold=1
</code></pre><p>您会注意到Vault在这里输出了几个密钥。不要清除您的终端，这些密钥在后面的步骤中会使用到。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Initializing-SSH.png" alt="Initializing SSH"></p><h4 id="启封您的vault" tabindex="-1"><strong>启封您的Vault</strong> <a class="header-anchor" href="#启封您的vault" aria-label="Permalink to “启封您的Vault”">​</a></h4><p>当一个Vault服务器启动时，它是密封的状态。在这种状态下，Vault被配置为知道物理存储在哪里及如何存取它，但不知道如何对其进行解密。Vault使用加密密钥来加密数据。这个密钥由&quot;主密钥&quot;加密，主密钥不保存。解密主密钥需要入口密钥。在这个例子中，我们使用了一个入口密钥来解密这个主密钥。</p><pre><code>vault unseal &lt;key 1&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Unsealing-SSH.png" alt="Unsealing SSH"></p><p>####<strong>为您的请求授权</strong></p><p>在执行任何操作之前，连接的客户端必须是被授权的。授权的过程是检验一个人或者机器是否如其所申明的那样具有正确的身份。这个身份用在向Vault发送请求时。为简单起见，我们将使用在步骤2中生成的root令牌，这个信息可以回滚终端屏幕看到。使用一个客户端令牌进行授权：</p><pre><code>vault auth &lt;root token&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Authorize-SSH.png" alt="Authorize SSH"></p><p>####<strong>读写保密信息</strong></p><p>现在Vault已经被设置妥当，我们可以开始读写默认挂载的秘密后端里面的秘密信息了。写在Vault中的秘密信息首先被加密，然后被写入后端存储中。后端存储机制绝不会看到未加密的信息，并且也没有在Vault之外解密的需要。</p><pre><code>vault write secret/hello value=world
</code></pre><p>当然，您接下来便可以读这个保密信息了：</p><pre><code>vault read secret/hello
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/RW_SSH.png" alt="RW_SSH"></p><p>####<strong>密封您的Vault</strong></p><p>还有一个用I来密封Vault的API。它将丢掉现在的加密密钥并需要另一个启封过程来恢复它。密封仅需要一个拥有root权限的操作者。这是一种罕见的&quot;打破玻璃过程&quot;的典型部分。</p><p>这种方式中，如果检测到一个入侵，Vault数据将会立刻被锁住，以便最小化损失。如果不能访问到主密钥碎片的话，就不能再次获取数据。</p><pre><code>vault seal
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Seal-Vault-SSH.png" alt="Seal Vault SSH"></p><p>这便是入门教程的结尾。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>`,56)),p("p",null,[t[4]||(t[4]=l("Vault是一个非常有用的应用，它提供了一个可靠且安全的存储关键信息的方式。另外，它在存储前加密关键信息、审计日志维护、以租期的方式获取秘密信息，且一旦租用期过期它将立刻收回秘密信息。Vault是平台无关的，并且可以免费下载和安装。要发掘Vault的更多信息，请访问其",-1)),o(a,{href:"https://vaultproject.io/"},{default:e(()=>[...t[3]||(t[3]=[l("官方网站",-1)])]),_:1}),t[5]||(t[5]=l("。",-1))]),t[21]||(t[21]=p("hr",null,null,-1)),p("p",null,[t[7]||(t[7]=l("via: ",-1)),o(a,{href:"http://linoxide.com/how-tos/secure-secret-store-vault/"},{default:e(()=>[...t[6]||(t[6]=[l("http://linoxide.com/how-tos/secure-secret-store-vault/",-1)])]),_:1})]),p("p",null,[t[11]||(t[11]=l("作者：",-1)),o(a,{href:"http://linoxide.com/author/arunrz/"},{default:e(()=>[...t[8]||(t[8]=[l("Aun Raza",-1)])]),_:1}),t[12]||(t[12]=l(" 译者：",-1)),o(a,{href:"https://github.com/wwy-hust"},{default:e(()=>[...t[9]||(t[9]=[l("wwy-hust",-1)])]),_:1}),t[13]||(t[13]=l(" 校对：",-1)),o(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[10]||(t[10]=[l("wxy",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=l("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[14]||(t[14]=[l("LCTT",-1)])]),_:1}),t[17]||(t[17]=l(" 原创翻译，",-1)),o(a,{href:"https://linux.cn/"},{default:e(()=>[...t[15]||(t[15]=[l("Linux中国",-1)])]),_:1}),t[18]||(t[18]=l(" 荣誉推出",-1))])])}const T=r(d,[["render",g]]);export{x as __pageData,T as default};
